def task_func(myString):
    urls = re.findall(r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+', myString)
    result_dict = {}

    for url in urls:
        try:
            parsed_url = urllib.parse.urlparse(url)
            if parsed_url.scheme == 'https':
                hostname = parsed_url.hostname

                # Ignore non-SSL connections or invalid hostnames
                if hostname is None or hostname.startswith('www.') or hostname.endswith('.local') or hostname.endswith('.in'):
                    continue

                # Get the SSL certificate information
                context = ssl.create_default_context()
                with socket.create_connection((hostname, 443)) as sock:
                    with context.wrap_socket(sock, server_hostname=hostname) as ssock:
                        cert = ssock.getpeercert()

                # Extract the expiration date from the certificate
                exp_date = datetime.datetime.strptime(cert['notAfter'], '%b %d %H:%M:%S %Y %Z')

                result_dict[hostname] = exp_date
        except Exception as e:
            print(f"Error processing {url}: {e}")

    return result_dict

