        columns = [th.get_text(strip=True) for th in data_rows[0].select('th')]
        rows = [[td.get_text(strip=True) for td in tr.select('td')] for tr in data_rows]

        df = pd.DataFrame(rows, columns=columns)
        return df

    except requests.exceptions.HTTPError as e:
        print(f"HTTP Error occurred: {str(e)}")
        return pd.DataFrame()
    except Exception as e:
        print(f"An unexpected error occurred: {str(e)}")
        return pd.DataFrame()

