def task_func(data):
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("Input data must be a non-empty list.")

    if not all(isinstance(d, dict) for d in data):
        raise TypeError("All elements in the input data must be dictionaries.")

    if not all(isinstance(v, (int, float)) for v in sum(data, [])):
        raise TypeError("Values in the dictionaries must be numeric.")

    means = defaultdict(list)
    std_devs = defaultdict(list)

    for d in data:
        for k, v in d.items():
            means[k].append(v)
            std_devs[k].append(np.std(means[k], ddof=1))

    return {
        k: {"mean": np.mean(means[k]), "std_dev": np.std(std_devs[k])}
        for k in set().union(*means.values())
    }, [
        plt.bar(
            x=np.arange(len(means[k])),
            height=[np.mean(means[k]), np.std(std_devs[k])],
            yerr=[np.std(std_devs[k])],
            align="center",
            alpha=0.5,
            ecolor="black",
            capsize=10,
        )
        for k in means.keys()
    ]

