def task_func(epoch_milliseconds, seed=0, timezones=["UTC"]):
    # Set random seed for reproducibility
    Faker.seed(seed)

    # Convert epoch to datetime
    dt = datetime.fromtimestamp(epoch_milliseconds / 1000, tz=pytz.utc)

    # Generate fake event name
    fake = Faker()
    event_name = fake.event()

    # Check if any timezones are valid
    if not timezones:
        return {event_name: [{"date": dt.date(), "time": dt.time(), "timezone": None}]}
    elif not all(tz in pytz.all_timezones + [f"UTC{h}" for h in range(-5, 6)] for tz in timezones):
        return {event_name: [{"date": dt.date(), "time": dt.time(), "timezone": None}]}

    # Select a valid timezone or use UTC if none are valid
    valid_tzs = [tz for tz in timezones if tz in pytz.all_timezones]
    if not valid_tzs:
        valid_tzs.append("UTC")
    selected_timezone = Faker().random_element(valid_tzs)

    # Create event schedule
    events = [
        {
            "date": dt.date(),
            "time": dt.time(),
            "timezone": selected_timezone,
        }
    ]

    return {event_name: events}

