def task_func(shape=(3, 3), low=1, high=10, seed=None):
    if not isinstance(shape, tuple) or len(shape) != 2:
        raise ValueError("Shape must be a tuple of length 2")

    if not isinstance(low, int) or not isinstance(high, int):
        raise TypeError("Low and high must be integers")

    if low >= high:
        raise ValueError("High must be greater than Low")

    rng = np.random.default_rng(seed)
    matrix = rng.integers(low, high+1, size=shape)

    def product_sum(matrix):
        return reduce(lambda x, y: x + y[0] * y[1], combinations(matrix.flatten(), 2), 0)

    result_matrix = matrix

    try:
        result = product_sum(result_matrix)
    except Exception as e:
        raise RuntimeError(f"An error occurred while calculating the sum of products: {e}")

    return result, result_matrix

