def task_func(script_path: str, temp_dir: str) -> str:
    try:
        # Create a temporary directory and move the script there
        temp_script = os.path.join(temp_dir, os.path.basename(script_path))
        shutil.move(script_path, temp_script)

        # Execute the script from the temporary directory
        result = subprocess.run([temp_script], capture_output=True, text=True)

        if result.returncode == 0:
            return f"Script executed successfully! {result.stdout}"
        else:
            return f"Script execution failed! Error: {result.stderr}"

    except Exception as e:
        return f"An error occurred while executing the script: {str(e)}"

    finally:
        # Clean up the temporary directory
        shutil.rmtree(temp_dir)

