def task_func(script_path: str, timeout: int = 60) -> str:
    try:
        # Check if the script exists
        if not os.path.exists(script_path):
            raise FileNotFoundError(f"File {script_path} does not exist.")

        # Execute the script in a separate thread and wait for its completion
        def execute_script():
            result = subprocess.run(
                [os.path.abspath(script_path)],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=False,
                timeout=timeout
            )
            if result.returncode == 0:
                print("Script executed successfully.")
                return "Script executed successfully."

            else:
                print("Terminating process due to timeout.")
                return "Terminating process due to timeout."

        t = threading.Thread(target=execute_script)
        t.start()
        t.join()

        return "Script executed successfully."

    except FileNotFoundError as e:
        return f"FileNotFoundError: {e}"

    except Exception as e:
        return f"An error occurred: {str(e)}"

