def task_func(process_name: str) -> int:
    count = 0

    try:
        # Get list of all processes
        pids = [int(x.split()[1]) for x in subprocess.check_output(['pgrep', '-f', process_name']).decode().splitlines()]
    except Exception as e:
        print(f"Error occurred while getting PID list: {e}")
        return 0

    if not pids:
        print("No processes found.")
        return 0

    for pid in pids:
        try:
            # Send SIGTERM to each process
            os.kill(pid, signal.SIGTERM)
            time.sleep(1)

            # Check if process has terminated
            if os.waitpid(pid, 0)[1] == 0:
                count += 1
        except Exception as e:
            print(f"Failed to stop process {pid}: {e}")

    return count

