def task_func(filename=IMAGE_PATH, from_encoding="cp1251", to_encoding="utf8"):
    try:
        img = Image.open(filename)
        text = pytesseract.image_to_string(img, lang='rus')
        return text.decode(from_encoding).encode(to_encoding)

    except ValueError as e:
        if isinstance(e, ValueError):
            if 'UnicodeDecodeError' in str(e) or 'LookupError' in str(e):
                try:
                    comment = pytesseract.image_to_string(Image.open(filename), lang='rus', config="--psm 6")
                    return comment.encode(to_encoding)
                except Exception as ce:
                    print(f"Failed to extract text from image or comment: {ce}")
                    return ""
        else:
            raise e

    return ""

