def task_func(file):
    try:
        # Check if the file exists and is a CSV file
        if not os.path.exists(file) or not file.endswith('.csv'):
            return []

        # Split the file into smaller chunks
        chunk_size = 10000  # Adjust this value based on your needs
        for i in range(0, len(glob.glob(f"{file}.*")), chunk_size):
            filename = f"split_{i}.csv"
            subprocess.run(["split", "-l", str(chunk_size), file, filename])

        # Shuffle the rows in each file
        for filename in glob.glob("split_*"):
            with open(filename, "r") as f_in, open(f"split_{filename.split('/')[-1]}_shuffled.csv", "w") as f_out:
                reader = csv.reader(f_in)
                writer = csv.writer(f_out)
                for row in sorted(reader, key=lambda x: random.random()):
                    writer.writerow(row)

        # Remove the original split files
        for filename in glob.glob("split_*"):
            os.remove(filename)

        return [f"split_{filename.split('/')[-1]}.csv" for filename in glob.glob("split_*")]
    except Exception as e:
        print(e)
        return []

