def task_func(logs: list):
    error_times = []
    total_time = 0

    for log in logs:
        match = re.search(r'ERROR\s+(\d{2}:\d{2})', log)
        if match:
            error_times.append(match.group(1))
            total_time += int(match.group(1).split(':')[0]) * 60 + int(match.group(1).split(':')[1])

    if not error_times:
        return [], None

    avg_time = total_time / len(error_times)

    return error_times, avg_time

