def task_func(f_list, file_path):
    if not isinstance(f_list, list) or len(f_list) == 0:
        raise ValueError("Invalid input: f_list must be a non-empty list.")

    try:
        df = pd.DataFrame(columns=['Function Name', 'Number of Arguments', 'Defaults', 'Annotations', 'Is Lambda'])

        for func in f_list:
            signature = inspect.signature(func)

            args = [arg.name for arg in signature.parameters.values()]
            num_args = len(args)

            defaults = {arg.name: arg.default for arg in signature.parameters.values()}
            default_values = ', '.join([f"{name}={default}" for name, default in defaults.items()])

            annotations = []
            for param in signature.parameters.values():
                annotation = str(param.annotation)
                if param.default != inspect.Parameter.empty:
                    annotation += " | Default="
                    annotation += str(defaults.get(param.name))

                annotations.append(annotation)

            is_lambda = False
            if hasattr(func, '__code__') and func.__code__.co_flags & inspect.CO_FUTURE_BORROWED_NAME:
                is_lambda = True

            df = df.append({
                'Function Name': func.__name__,
                'Number of Arguments': num_args,
                'Defaults': default_values,
                'Annotations': ', '.join(annotations),
                'Is Lambda': is_lambda
            }, ignore_index=True)

        df.to_csv(file_path, index=False)
    except Exception as e:
        print(f"An error occurred while exporting to CSV: {e}")
        return None

    return df

