def task_func(data_list, seed=42):
    # Set the random seed for reproducibility
    random.seed(seed)

    def normalize_spaces(s):
        return re.sub(r'\s+', ' ', s).strip()

    df = pd.DataFrame(columns=['Original String', 'Randomized String'])

    for i, data in enumerate(data_list):
        orig_str = data.replace(',', '').replace(';', '')
        rand_str = ','.join(random.sample(orig_str.split(','), len(orig_str.split(','))))
        normalized_orig_str = normalize_spaces(orig_str)
        normalized_rand_str = normalize_spaces(rand_str)

        df.loc[i] = [normalized_orig_str, normalized_rand_str]

    return df

def task_func(n, seed=None):
    if seed is None or not isinstance(seed, int):
        raise ValueError("Seed must be an integer")

    result = defaultdict(list)
    chars = [chr(i) for i in range(ord('a'), ord('z')+1)]
    random.seed(seed)

    while len(result) < n:
        char = random.choice(chars)
        count = random.randint(0, n - len(result[char]))
        for _ in range(count):
            result[char].append(char)

    return dict(result)

