            if field in d:
                means[field].append(d[field])
                medians[field].append(np.median([x for x in d[field] if isinstance(x, int)]))

    result_dict = {}
    for field in all_fields:
        result_dict[field] = {
            "mean": np.mean(means[field]),
            "median": medians[field][0],
        }

